def normshape(cc):
 return frozenset((r-min(x for x,y in cc),c-min(y for x,y in cc)) for r,c in cc)
def variants(sh):
 out=[]
 for flip in [False,True]:
  a=set((r, -c if flip else c) for r,c in sh)
  for k in range(4):
   rs=[r for r,c in a]; cs=[c for r,c in a]
   s=frozenset((r-min(rs),c-min(cs)) for r,c in a)
   out.append(s)
   a={(c,-r) for r,c in a}
 return out
