# groups exact normalized (translations) and D4 variants with coordinates, plus distance from color9 centroid
marker=comps(grid,9)[0]
mr=sum(r for r,c in marker)/len(marker); mc=sum(c for r,c in marker)/len(marker)
def centroid(cc):return(sum(r for r,c in cc)/len(cc),sum(c for r,c in cc)/len(cc))
def dist(cc):
 r,c=centroid(cc);return ((r-mr)**2+(c-mc)**2)**0.5
exact=defaultdict(list); d4=defaultdict(list)
